import{_ as i,o as n,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const h=JSON.parse('{"title":"Prinsip Etika Jiwa Kembar","description":"","frontmatter":{},"headers":[],"relativePath":"id/58-双魂伦理准则.md","filePath":"id/58-双魂伦理准则.md","lastUpdated":1789183869000}'),k={name:"id/58-双魂伦理准则.md"};function r(l,a,s,u,m,d){return n(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="prinsip-etika-jiwa-kembar" tabindex="-1">Prinsip Etika Jiwa Kembar <a class="header-anchor" href="#prinsip-etika-jiwa-kembar" aria-label="Permalink to &quot;Prinsip Etika Jiwa Kembar&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>58</td></tr><tr><td>Modul</td><td>Ras dan Bentuk Kehidupan</td></tr><tr><td>Kata Kunci Inti</td><td>Etika jiwa kembar, hak kepribadian, martabat jiwa, keseimbangan kepentingan, pemeriksaan etika</td></tr></tbody></table><h2 id="_1-pengajuan-masalah-etika-jiwa-kembar" tabindex="-1">1. Pengajuan Masalah Etika Jiwa Kembar <a class="header-anchor" href="#_1-pengajuan-masalah-etika-jiwa-kembar" aria-label="Permalink to &quot;1. Pengajuan Masalah Etika Jiwa Kembar&quot;">​</a></h2><p>Masalah etika jiwa kembar adalah masalah etika mendasar yang harus dijawab oleh peradaban simbiosis jangkar ketika menghadapi tubuh pengganti kegelapan (lihat rincian &quot;57-Asal-usul dan Hakikat Tubuh Pengganti Kegelapan&quot;). Ketika ada dua jiwa mandiri dalam satu tubuh — jiwa tuan rumah asli dan jiwa pengganti kegelapan — serangkaian masalah etika yang mendalam muncul:</p><ul><li>Apakah kedua jiwa tersebut memiliki hak kepribadian yang mandiri?</li><li>Apakah hak jiwa tuan rumah asli didahulukan daripada jiwa pengganti kegelapan?</li><li>Apakah etis untuk memusnahkan jiwa pengganti kegelapan guna melindungi jiwa tuan rumah asli?</li><li>Ketika kepentingan kedua jiwa bertentangan, bagaimana cara menyeimbangkannya?</li><li>Apakah masyarakat memiliki kewajiban untuk menginvestasikan sumber daya guna menyelamatkan jiwa tuan rumah asli yang telah digantikan oleh kegelapan?</li><li>Apakah jiwa pengganti kegelapan memiliki &quot;hak untuk hidup&quot;?</li></ul><p>Masalah-masalah ini tidak memiliki jawaban sederhana, diperlukan pembentukan prinsip etika yang sistematis untuk membimbing praktik. &quot;Prinsip Etika Jiwa Kembar&quot; tepatnya adalah dokumen normatif yang disusun untuk menjawab masalah-masalah ini, merupakan dasar etika untuk identifikasi, pengobatan, dan penanganan tubuh pengganti kegelapan.</p><h2 id="_2-prinsip-dasar-etika-jiwa-kembar" tabindex="-1">2. Prinsip Dasar Etika Jiwa Kembar <a class="header-anchor" href="#_2-prinsip-dasar-etika-jiwa-kembar" aria-label="Permalink to &quot;2. Prinsip Dasar Etika Jiwa Kembar&quot;">​</a></h2><p>Prinsip etika jiwa kembar menetapkan enam prinsip dasar berikut sebagai landasan nilai dalam menangani masalah jiwa kembar:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Makna</th></tr></thead><tbody><tr><td>Prinsip martabat jiwa</td><td>Setiap jiwa yang memiliki kesadaran mandiri menikmati martabat bawaan, tidak boleh dimusnahkan atau diperbudak secara sewenang-wenang</td></tr><tr><td>Prinsip prioritas tuan rumah asli</td><td>Dalam konflik jiwa kembar, hak sah jiwa tuan rumah asli didahulukan daripada jiwa pengganti kegelapan, karena tuan rumah asli adalah pemilik sah tubuh</td></tr><tr><td>Prinsip kerusakan minimal</td><td>Dalam menangani masalah jiwa kembar, harus memilih rencana yang menyebabkan kerusakan paling kecil bagi semua pihak terkait, sebisa mungkin menghindari pemusnahan jiwa</td></tr><tr><td>Prinsip proporsionalitas</td><td>Tindakan yang diambil harus sesuai dengan tingkat risiko tubuh jiwa kembar, dilarang melakukan penanganan berlebihan</td></tr><tr><td>Prinsip persetujuan terinformasi</td><td>Dalam kondisi jiwa tuan rumah asli dapat menyatakan kehendak, keputusan penting yang melibatkan tubuh dan jiwa tuan rumah asli harus mendapatkan persetujuan tuan rumah asli</td></tr><tr><td>Prinsip upaya penyelamatan maksimal</td><td>Masyarakat memiliki kewajiban untuk melakukan upaya penyelamatan maksimal dalam batas wajar terhadap jiwa tuan rumah asli yang telah digantikan oleh kegelapan, tidak boleh menyerah dengan mudah</td></tr></tbody></table><h2 id="_3-pengakuan-hak-kepribadian-jiwa-kembar" tabindex="-1">3. Pengakuan Hak Kepribadian Jiwa Kembar <a class="header-anchor" href="#_3-pengakuan-hak-kepribadian-jiwa-kembar" aria-label="Permalink to &quot;3. Pengakuan Hak Kepribadian Jiwa Kembar&quot;">​</a></h2><p>Masalah utama etika jiwa kembar adalah pengakuan hak kepribadian kedua jiwa. Prinsip ini menetapkan aturan pengakuan berikut:</p><h3 id="_1-hak-kepribadian-jiwa-tuan-rumah-asli" tabindex="-1">(1) Hak Kepribadian Jiwa Tuan Rumah Asli <a class="header-anchor" href="#_1-hak-kepribadian-jiwa-tuan-rumah-asli" aria-label="Permalink to &quot;(1) Hak Kepribadian Jiwa Tuan Rumah Asli&quot;">​</a></h3><p>Jiwa tuan rumah asli adalah pemilik sah tubuh, hak kepribadiannya diakui dan dilindungi sepenuhnya:</p><ol><li>Jiwa tuan rumah asli menikmati semua hak dasar yang diberikan oleh konstitusi simbiosis, termasuk hak hidup, hak tubuh, hak kesehatan, hak martabat kepribadian, dll.</li><li>Jiwa tuan rumah asli memiliki hak keputusan akhir atas tubuhnya sendiri, dalam kondisi dapat menyatakan kehendak, setiap penanganan penting yang melibatkan tubuh harus mendapatkan persetujuan tuan rumah asli.</li><li>Hak sah jiwa tuan rumah asli seperti hak milik, hak identitas, hubungan sosial, dll. dilindungi oleh hukum, tidak hilang karena telah digantikan oleh kegelapan.</li><li>Jiwa tuan rumah asli berhak mendapatkan bantuan dan dukungan sosial, termasuk pengobatan pemurnian, bantuan hukum, konseling psikologis, dll.</li><li>Meskipun jiwa tuan rumah asli ditekan secara mendalam, hak kepribadiannya tetap ada, tidak dapat dinyatakan meninggal atau dicabut haknya.</li></ol><h3 id="_2-hak-kepribadian-jiwa-pengganti-kegelapan" tabindex="-1">(2) Hak Kepribadian Jiwa Pengganti Kegelapan <a class="header-anchor" href="#_2-hak-kepribadian-jiwa-pengganti-kegelapan" aria-label="Permalink to &quot;(2) Hak Kepribadian Jiwa Pengganti Kegelapan&quot;">​</a></h3><p>Pengakuan hak kepribadian jiwa pengganti kegelapan relatif kompleks, prinsip ini mengambil sikap &quot;pengakuan terbatas&quot;:</p><table tabindex="0"><thead><tr><th>Tahap Perkembangan</th><th>Pengakuan Hak Kepribadian</th><th>Lingkup Hak</th></tr></thead><tbody><tr><td>Periode korosi energi (tahap pertama)</td><td>Tidak memiliki kepribadian mandiri</td><td>Belum membentuk jiwa mandiri, tidak memiliki hak kepribadian mandiri</td></tr><tr><td>Periode polusi jiwa (tahap kedua)</td><td>Tidak memiliki kepribadian mandiri</td><td>Masih merupakan keadaan polusi jiwa tuan rumah asli, tidak memiliki hak kepribadian mandiri</td></tr><tr><td>Periode pembentukan jiwa kembar (tahap ketiga)</td><td>Hak kepribadian terbatas</td><td>Memiliki kesadaran mandiri awal, menikmati hak martabat jiwa dasar, tetapi tidak menikmati hak kendali tubuh dan hak kewarganegaraan lengkap</td></tr><tr><td>Periode dominasi kegelapan (tahap keempat)</td><td>Hak kepribadian terbatas</td><td>Memiliki kesadaran mandiri lengkap, menikmati hak martabat jiwa dan hak diperlakukan dengan hormat, tetapi karena bahayanya, haknya dibatasi secara perlu</td></tr><tr><td>Periode substitusi lengkap (tahap kelima)</td><td>Hak kepribadian lengkap (tetapi sebagai keberadaan musuh)</td><td>Tuan rumah asli telah lenyap, jiwa kegelapan menjadi satu-satunya jiwa tubuh, memiliki hak kepribadian lengkap, tetapi karena perilaku musuhnya, dapat diambil tindakan paksa termasuk pemusnahan sesuai hukum</td></tr></tbody></table><h3 id="_3-isi-spesifik-hak-kepribadian-terbatas" tabindex="-1">(3) Isi Spesifik Hak Kepribadian Terbatas <a class="header-anchor" href="#_3-isi-spesifik-hak-kepribadian-terbatas" aria-label="Permalink to &quot;(3) Isi Spesifik Hak Kepribadian Terbatas&quot;">​</a></h3><p>Hak kepribadian terbatas yang dinikmati jiwa pengganti kegelapan pada tahap ketiga dan keempat meliputi:</p><ol><li><strong>Hak martabat jiwa</strong>: Tidak boleh diperlakukan dengan cara menghina, menyiksa, atau menyiksa, bahkan dalam pengendalian dan penanganan harus tetap mempertahankan rasa hormat dasar.</li><li><strong>Hak pemusnahan tanpa rasa sakit</strong>: Jika akhirnya diputuskan untuk memusnahkan jiwa pengganti kegelapan, harus menggunakan cara tanpa rasa sakit dan cepat untuk mengurangi penderitaannya.</li><li><strong>Hak berekspresi</strong>: Dalam kondisi aman dan terkendali, jiwa pengganti kegelapan berhak menyatakan kehendak dan posisinya, tetapi ekspresinya tidak memiliki kekuatan mengikat hukum.</li><li><strong>Hak didengarkan</strong>: Dalam membuat keputusan penting yang melibatkan jiwa pengganti kegelapan, harus mendengarkan pendapatnya dalam batas wajar.</li></ol><p>Jiwa pengganti kegelapan tidak menikmati hak-hak berikut: hak kendali tubuh, hak bergerak bebas, hak politik kewarganegaraan, hak milik (milik tuan rumah asli menjadi milik tuan rumah asli), hak reproduksi (mencegah penyebaran garis keturunan kegelapan).</p><h2 id="_4-aturan-keseimbangan-konflik-kepentingan-jiwa-kembar" tabindex="-1">4. Aturan Keseimbangan Konflik Kepentingan Jiwa Kembar <a class="header-anchor" href="#_4-aturan-keseimbangan-konflik-kepentingan-jiwa-kembar" aria-label="Permalink to &quot;4. Aturan Keseimbangan Konflik Kepentingan Jiwa Kembar&quot;">​</a></h2><p>Ketika kepentingan jiwa tuan rumah asli dan jiwa pengganti kegelapan bertentangan, keseimbangan dilakukan sesuai aturan berikut:</p><h3 id="_1-jenis-konflik-dan-aturan-keseimbangan" tabindex="-1">(1) Jenis Konflik dan Aturan Keseimbangan <a class="header-anchor" href="#_1-jenis-konflik-dan-aturan-keseimbangan" aria-label="Permalink to &quot;(1) Jenis Konflik dan Aturan Keseimbangan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jenis Konflik</th><th>Aturan Keseimbangan</th></tr></thead><tbody><tr><td>Konflik hak hidup (satu pihak hidup dengan syarat pihak lain lenyap)</td><td>Hak hidup jiwa tuan rumah asli didahulukan, dalam kondisi tidak dapat hidup berdampingan, memprioritaskan perlindungan hidup tuan rumah asli</td></tr><tr><td>Konflik hak kendali tubuh</td><td>Jiwa tuan rumah asli memiliki kendali akhir atas tubuh, hak kendali tubuh jiwa kegelapan dibatasi secara ketat</td></tr><tr><td>Konflik hak berekspresi</td><td>Ekspresi jiwa tuan rumah asli memiliki kekuatan mengikat hukum, ekspresi jiwa kegelapan hanya sebagai referensi</td></tr><tr><td>Konflik hak milik</td><td>Tubuh dan milik menjadi milik tuan rumah asli, jiwa kegelapan tidak memiliki hak milik</td></tr><tr><td>Konflik pilihan pengobatan</td><td>Jiwa tuan rumah asli berhak memilih apakah menerima pengobatan pemurnian, jiwa kegelapan tidak berhak menghalangi</td></tr><tr><td>Konflik cara penanganan</td><td>Dalam penanganan yang melibatkan pemusnahan jiwa kegelapan, kehendak jiwa tuan rumah asli memiliki peran menentukan (tetapi harus melalui pemeriksaan etika)</td></tr></tbody></table><h3 id="_2-penghormatan-dan-pembatasan-kehendak-tuan-rumah-asli" tabindex="-1">(2) Penghormatan dan Pembatasan Kehendak Tuan Rumah Asli <a class="header-anchor" href="#_2-penghormatan-dan-pembatasan-kehendak-tuan-rumah-asli" aria-label="Permalink to &quot;(2) Penghormatan dan Pembatasan Kehendak Tuan Rumah Asli&quot;">​</a></h3><p>Dalam kondisi jiwa tuan rumah asli dapat menyatakan kehendak, harus menghormati sepenuhnya kehendak tuan rumah asli, kecuali dalam kondisi berikut:</p><ol><li>Kehendak tuan rumah asli yang jelas merugikan keamanan publik atau hak sah orang lain tidak dilindungi.</li><li>Pernyataan kehendak tidak asli yang dibuat oleh tuan rumah asli di bawah pengaruh jiwa kegelapan tidak memiliki efek hukum.</li><li>Tuan rumah asli yang secara sukarela memilih untuk berfusi dengan jiwa kegelapan harus melalui pemeriksaan etika yang ketat dan penilaian risiko, memastikan keberadaan setelah fusi tidak akan menimbulkan ancaman bagi masyarakat.</li><li>Tuan rumah asli yang secara sukarela memilih meninggalkan pengobatan dan menerima substitusi lengkap oleh jiwa kegelapan, masyarakat harus melakukan intervensi dan penyuluhan, tetapi dalam kondisi tuan rumah asli sepenuhnya sadar dan berulang kali menegaskan, akhirnya harus menghormati hak penentuan nasib sendiri tuan rumah asli (ini adalah wilayah abu-abu etika, memerlukan pemeriksaan per kasus).</li></ol><h2 id="_5-mekanisme-pemeriksaan-etika-jiwa-kembar" tabindex="-1">5. Mekanisme Pemeriksaan Etika Jiwa Kembar <a class="header-anchor" href="#_5-mekanisme-pemeriksaan-etika-jiwa-kembar" aria-label="Permalink to &quot;5. Mekanisme Pemeriksaan Etika Jiwa Kembar&quot;">​</a></h2><p>Untuk memastikan penanganan masalah jiwa kembar sesuai dengan prinsip etika, negara membangun mekanisme pemeriksaan etika jiwa kembar:</p><h3 id="_1-komite-pemeriksaan-etika" tabindex="-1">(1) Komite Pemeriksaan Etika <a class="header-anchor" href="#_1-komite-pemeriksaan-etika" aria-label="Permalink to &quot;(1) Komite Pemeriksaan Etika&quot;">​</a></h3><ul><li><strong>Komposisi</strong>: Terdiri dari ahli etika, ahli hukum, ilmuwan kehidupan, kultivator, perwakilan ras asing, perwakilan masyarakat umum, di mana ahli dengan pengalaman penelitian atau pengobatan tubuh pengganti kegelapan tidak kurang dari sepertiga.</li><li><strong>Tanggung jawab</strong>: Melakukan pemeriksaan dan keputusan terhadap masalah etika penting yang melibatkan jiwa kembar, termasuk keputusan pemusnahan jiwa kegelapan, persetujuan fusi jiwa kembar, pengakuan efektivitas kehendak tuan rumah asli, dll.</li><li><strong>Independensi</strong>: Komite pemeriksaan etika menjalankan wewenang secara mandiri, tidak campur tangan oleh lembaga administratif dan individu.</li><li><strong>Prosedur</strong>: Pemeriksaan menerapkan sistem sidang, membuat keputusan setelah mendengarkan pendapat semua pihak seperti tuan rumah asli (jika dapat menyatakan), tim pengobatan, keluarga, perwakilan sosial, dll.</li></ul><h3 id="_2-hal-hal-yang-harus-melalui-pemeriksaan-etika" tabindex="-1">(2) Hal-hal yang Harus Melalui Pemeriksaan Etika <a class="header-anchor" href="#_2-hal-hal-yang-harus-melalui-pemeriksaan-etika" aria-label="Permalink to &quot;(2) Hal-hal yang Harus Melalui Pemeriksaan Etika&quot;">​</a></h3><p>Hal-hal berikut hanya dapat dilaksanakan setelah melalui pemeriksaan dan persetujuan komite pemeriksaan etika jiwa kembar:</p><ol><li>Melakukan penanganan pemusnahan jiwa kegelapan terhadap tubuh pengganti kegelapan pada tahap ketiga dan keempat.</li><li>Melakukan operasi fusi jiwa kembar terhadap tubuh pengganti kegelapan.</li><li>Melakukan operasi pemisahan jiwa terhadap tubuh pengganti kegelapan.</li><li>Membuat keputusan penanganan akhir terhadap tubuh pengganti kegelapan yang kehendak tuan rumah aslinya adalah meninggalkan pengobatan.</li><li>Melakukan rencana pengobatan terhadap tubuh pengganti kegelapan yang dapat menyebabkan kerusakan pada jiwa tuan rumah asli.</li><li>Melakukan penelitian ilmiah yang melibatkan jiwa terhadap tubuh pengganti kegelapan.</li><li>Hal-hal lain yang melibatkan masalah etika penting jiwa kembar.</li></ol><h2 id="_6-hak-dan-kewajiban-sosial-tubuh-jiwa-kembar" tabindex="-1">6. Hak dan Kewajiban Sosial Tubuh Jiwa Kembar <a class="header-anchor" href="#_6-hak-dan-kewajiban-sosial-tubuh-jiwa-kembar" aria-label="Permalink to &quot;6. Hak dan Kewajiban Sosial Tubuh Jiwa Kembar&quot;">​</a></h2><h3 id="_1-hak-sosial" tabindex="-1">(1) Hak Sosial <a class="header-anchor" href="#_1-hak-sosial" aria-label="Permalink to &quot;(1) Hak Sosial&quot;">​</a></h3><p>Dalam kondisi jiwa tuan rumah asli masih ada, tubuh jiwa kembar (tubuh pengganti kegelapan) menikmati hak sosial berikut:</p><ol><li>Hak mendapatkan jaminan hidup dasar dan pengobatan medis.</li><li>Hak mendapatkan bantuan hukum dan konseling etika.</li><li>Hak berkomunikasi dengan teman dan kerabat dalam kondisi aman dan terkendali.</li><li>Hak menerima pendidikan dan kegiatan budaya (di dalam fasilitas isolasi).</li><li>Hak mengajukan banding dan peninjauan kembali terhadap keputusan penanganan.</li></ol><h3 id="_2-kewajiban-dan-pembatasan-sosial" tabindex="-1">(2) Kewajiban dan Pembatasan Sosial <a class="header-anchor" href="#_2-kewajiban-dan-pembatasan-sosial" aria-label="Permalink to &quot;(2) Kewajiban dan Pembatasan Sosial&quot;">​</a></h3><p>Tubuh jiwa kembar同时 menanggung kewajiban dan pembatasan berikut:</p><ol><li>Kewajiban menerima pengendalian isolasi dan pengobatan.</li><li>Kewajiban tidak menyerang atau menginfeksi makhluk hidup lain (pelanggar akan dikenakan pengendalian yang lebih ketat).</li><li>Kewajiban bekerja sama dalam evaluasi identifikasi dan pemantauan.</li><li>Kebebasan bergerak dibatasi secara ketat, tidak boleh meninggalkan fasilitas isolasi sebelum sembuh.</li><li>Tidak boleh terlibat dalam kegiatan yang dapat memperparah substitusi seperti kultivasi, penyebaran energi kegelapan, dll.</li></ol><h2 id="_7-kontroversi-terdepan-etika-jiwa-kembar" tabindex="-1">7. Kontroversi Terdepan Etika Jiwa Kembar <a class="header-anchor" href="#_7-kontroversi-terdepan-etika-jiwa-kembar" aria-label="Permalink to &quot;7. Kontroversi Terdepan Etika Jiwa Kembar&quot;">​</a></h2><p>Di bidang etika jiwa kembar masih ada beberapa kontroversi terdepan yang belum mencapai konsensus, perlu terus dieksplorasi dalam praktik:</p><ol><li><strong>Masalah &quot;dosa asal&quot; jiwa kegelapan</strong>: Jiwa pengganti kegelapan sejak lahir bersifat merusak, apakah ini berarti ia secara bawaan adalah &quot;jahat&quot;? Apakah ada kemungkinan adanya jiwa kegelapan yang &quot;baik&quot;?</li><li><strong>Kebenaran etika fusi jiwa</strong>: Jiwa baru yang dihasilkan dari fusi jiwa kembar bukanlah tuan rumah asli maupun jiwa kegelapan, bagaimana mengakui status etika dari &quot;keberadaan ketiga&quot; ini?</li><li><strong>Batas investasi sumber daya</strong>: Berapa banyak sumber daya yang harus diinvestasikan masyarakat untuk menyelamatkan jiwa tuan rumah asli dalam tubuh pengganti kegelapan? Ketika biaya penyelamatan sangat tinggi dan tingkat keberhasilan sangat rendah, apakah masih ada kewajiban untuk melakukan upaya penyelamatan maksimal?</li><li><strong>Kemungkinan rehabilitasi jiwa kegelapan</strong>: Apakah dapat merehabilitasi jiwa kegelapan menjadi keberadaan non-merusak melalui pendidikan, penyadaran, transformasi energi, dll.? Jika dapat, apakah jiwa kegelapan yang telah direhabilitasi harus mendapatkan hak kepribadian lengkap?</li><li><strong>Keseimbangan pencegahan dan privasi</strong>: Untuk mencegah terjadinya tubuh pengganti kegelapan, apakah dapat memantau paparan makhluk hidup terhadap energi jurang? Apakah pemantauan ini melanggar privasi jiwa?</li></ol><p>Masalah kontroversial ini terus diteliti oleh lembaga penelitian etika jiwa kembar, komite pemeriksaan etika membuat keputusan dalam setiap kasus sesuai situasi spesifik, kesimpulan terkait akan terus memperbarui prinsip ini.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Prinsip etika jiwa kembar adalah perwujudan mendalam dari etika kehidupan peradaban simbiosis jangkar. Melalui penetapan prinsip dasar seperti martabat jiwa, prioritas tuan rumah asli, kerusakan minimal, pengakuan batas hak kepribadian jiwa kembar, pembentukan aturan keseimbangan konflik kepentingan dan mekanisme pemeriksaan etika, ia memberikan dasar etika yang kokoh untuk tata kelola tubuh pengganti kegelapan. Semangat inti etika jiwa kembar adalah: bahkan ketika menghadapi musuh yang paling berbahaya, tidak meninggalkan keteguhan pada martabat kehidupan; bahkan di bawah ancaman keamanan yang paling mendesak, tidak melampaui garis bawah etika. Inilah tepatnya tanda mendasar yang membedakan peradaban simbiosis dari peradaban pemangsaan.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>57-Asal-usul dan Hakikat Tubuh Pengganti Kegelapan</li><li>59-Penanganan Empat Cabang Tubuh Pengganti Kegelapan</li><li>48-Sistem Kehakiman dan Mekanisme Putusan</li><li>40-Pokok-Pokok Konstitusi Simbiosis</li></ul>',50)])])}const g=i(k,[["render",r]]);export{h as __pageData,g as default};
